import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const script='design/simular-32-fluxo-sem-poderes-20261007.mjs';let s=fs.readFileSync(script,'utf8');s=s.replaceAll("fs.readFile(import.meta.url,'utf8')","fs.readFile(new URL(import.meta.url),'utf8')");fs.writeFileSync(script,s);
const hash=s=>createHash('sha256').update(s).digest('hex');const pilotHash=hash(s);
for(const mode of ['controle','fluxo']){const out='design/testes-2026-10-07-32-'+mode+'-sem-poderes',data=JSON.parse(fs.readFileSync(out+'/parcial.json')),prior=JSON.parse(fs.readFileSync(out+'/resultados.json'));const {games,metrics,powerStats}=data;assert.equal(games.length,32);assert.equal(games.at(-1).n,32);assert.ok(games.every(g=>!g.trace.some(a=>a.type==='patronPower')));
const catalog=JSON.parse(fs.readFileSync(mode==='controle'?'design/testes-2026-10-07-48-patrono20/catalogo-testado.json':'mesa-nova/cartas.json'));assert.equal(prior.catalogHash,hash(JSON.stringify(catalog)));const sources=Object.fromEntries(Object.keys(prior.hashes).map(n=>[n,fs.readFileSync('mesa-nova/'+n,'utf8')]));for(const [n,text] of Object.entries(sources))assert.equal(prior.hashes[n],hash(text));
const pairs=[['forja','fluxo'],['fluxo','ruptura']];const summary={games:32,wins:Object.fromEntries(['forja','fluxo','ruptura','empate'].map(k=>[k,games.filter(g=>g.winner===k).length])),meanRounds:games.reduce((n,g)=>n+g.rounds,0)/games.length,firstWins:games.filter(g=>g.first===g.winner).length,matchups:pairs.map(pair=>({pair:pair.join(' x '),games:games.filter(g=>g.pair===pair.join(' x ')).length,wins:Object.fromEntries([...pair,'empate'].map(k=>[k,games.filter(g=>g.pair===pair.join(' x ')&&g.winner===k).length]))})),policies:['imediato','planejado'].map(mode=>({mode,appearances:games.flatMap(g=>g.players).filter(p=>p.mode===mode).length,wins:games.filter(g=>g.players.some(p=>p.mode===mode&&p.deck===g.winner)).length})),metrics,powerStats};
fs.writeFileSync(out+'/resultados.json',JSON.stringify({method:prior.method+' Formação também considera posições livres para Miragem.',finalization:'32 partidas completas recuperadas de parcial.json após erro de conversão file: URL na gravação final. O caminho foi corrigido; decisões e métricas não foram alteradas.',hashes:prior.hashes,catalogHash:hash(JSON.stringify(catalog)),pilotHash,summary,games},null,2));fs.writeFileSync(out+'/catalogo-testado.json',JSON.stringify(catalog,null,2));fs.writeFileSync(out+'/partidas.csv','partida;semente;confronto;primeiro;vencedor;rodadas;combates;modoA;modoB\n'+games.map(g=>[g.n,g.seed,g.pair,g.first,g.winner,g.rounds,g.combats,...g.modes].join(';')).join('\n'));console.log(mode,JSON.stringify({...summary,metrics:undefined}));}
